describe("jsnum.FromString", function()
    it("matches Number(string)", function()
        local cases = {
            { "", "0x0000000000000000" },
            { " ", "0x0000000000000000" },
            { "0", "0x0000000000000000" },
            { "-0", "0x8000000000000000" },
            { "+0", "0x0000000000000000" },
            { "1", "0x3ff0000000000000" },
            { "+1", "0x3ff0000000000000" },
            { "-1", "0xbff0000000000000" },
            { "  42  ", "0x4045000000000000" },
            { "\009\01042\226\128\168", "0x4045000000000000" },
            { "\194\16042\227\128\128", "0x4045000000000000" },
            { "\239\187\1917", "0x401c000000000000" },
            { "1.5", "0x3ff8000000000000" },
            { "-1.5", "0xbff8000000000000" },
            { ".5", "0x3fe0000000000000" },
            { "5.", "0x4014000000000000" },
            { ".", "NaN" },
            { "-.", "NaN" },
            { "+.5", "0x3fe0000000000000" },
            { "1e3", "0x408f400000000000" },
            { "1E3", "0x408f400000000000" },
            { "1e+3", "0x408f400000000000" },
            { "1e-3", "0x3f50624dd2f1a9fc" },
            { "1e", "NaN" },
            { "e3", "NaN" },
            { "1.e3", "0x408f400000000000" },
            { ".1e-2", "0x3f50624dd2f1a9fc" },
            { "00012", "0x4028000000000000" },
            { "0012.50", "0x4029000000000000" },
            { "0x10", "0x4030000000000000" },
            { "0X1f", "0x403f000000000000" },
            { "0xg", "NaN" },
            { "0x", "NaN" },
            { "0b101", "0x4014000000000000" },
            { "0B2", "NaN" },
            { "0o17", "0x402e000000000000" },
            { "0O8", "NaN" },
            { "-0x10", "NaN" },
            { "+0x10", "NaN" },
            { "Infinity", "0x7ff0000000000000" },
            { "-Infinity", "0xfff0000000000000" },
            { "+Infinity", "0x7ff0000000000000" },
            { "infinity", "NaN" },
            { "NaN", "NaN" },
            { "1_000", "NaN" },
            { "12abc", "NaN" },
            { "abc", "NaN" },
            { "1.2.3", "NaN" },
            { "1e1e1", "NaN" },
            { "--1", "NaN" },
            { "+-1", "NaN" },
            { "0.1", "0x3fb999999999999a" },
            { "0.30000000000000004", "0x3fd3333333333334" },
            { "123456789012345678901234567890", "0x45f8ee90ff6c373e" },
            { "0x1fffffffffffffffff", "0x4440000000000000" },
            { "0x20000000000000100", "0x4400000000000000" },
            { "0x20000000000000101", "0x4400000000000000" },
            { "0x20000000000000180", "0x4400000000000000" },
            { "0b1111111111111111111111111111111111111111111111111111111111111111111111", "0x4450000000000000" },
            { "0o777777777777777777777777777777", "0x4590000000000000" },
            { "1e400", "0x7ff0000000000000" },
            { "-1e400", "0xfff0000000000000" },
            { "1e-400", "0x0000000000000000" },
            { "4.9e-324", "0x0000000000000001" },
            { "2.4703282292062328e-324", "0x0000000000000001" },
            { "2.4703282292062327e-324", "0x0000000000000000" },
            { "9007199254740993", "0x4340000000000000" },
            { "18446744073709551615", "0x43f0000000000000" },
            { "18446744073709551616", "0x43f0000000000000" },
            { "99999999999999999999999", "0x44b52d02c7e14af6" },
            { "1e00000000005", "0x40f86a0000000000" },
            { "1e-0000000001", "0x3fb999999999999a" },
            { "0.000000000000000000000000000000000000001", "0x37d5c72fb1552d83" },
            { "", "0x7fefffffffffffff" },
            { "1.7976931348623159e308", "0x7ff0000000000000" },
            { "\195\169", "NaN" },
            { "1\194\160", "0x3ff0000000000000" },
        }
        for _, c in ipairs(cases) do
            local v = jsnum.FromString(c[1])
            if c[2] == "NaN" then
                assert(v ~= v, "expected NaN for " .. c[1])
            else
                assert.are.equal(c[2], bits(v), "for " .. c[1])
            end
        end
    end)
end)

describe("jsnum round trip", function()
    it("FromString(Number_String(x)) == x", function()
        for i = 1, 2000 do
            local x = (math.random() - 0.5) * 10 ^ math.random(-30, 30)
            assert.are.equal(x, jsnum.FromString(jsnum.Number_String(x)))
        end
    end)
end)

