describe("jsnum.Number_Remainder", function()
    it("matches JS %", function()
        assert.are.equal("0x3ff8000000000000", bits(jsnum.Number_Remainder(5.5, 2)))
        assert.are.equal("0xbff8000000000000", bits(jsnum.Number_Remainder(-5.5, 2)))
        assert.is_true(jsnum.Number_IsNaN(jsnum.Number_Remainder(5, -0.0)))
        assert.is_true(jsnum.Number_IsNaN(jsnum.Number_Remainder(math.huge, 2)))
        assert.are.equal("0x4000000000000000", bits(jsnum.Number_Remainder(2, math.huge)))
        assert.are.equal("0x8000000000000000", bits(jsnum.Number_Remainder(-0.0, 5)))
        assert.are.equal("0x3ffc408f4350ed98", bits(jsnum.Number_Remainder(1e+300, 3.7)))
        assert.are.equal("0x3fb9999999999998", bits(jsnum.Number_Remainder(0.3, 0.1)))
    end)
end)

