describe("jsnum.PseudoBigInt", function()
    it("parses and prints", function()
        assert.are.equal("1208925819614629174706175", jsnum.ParsePseudoBigInt("0xFFFFFFFFFFFFFFFFFFFFn"))
        assert.are.equal("11", jsnum.ParsePseudoBigInt("0b1011n"))
        assert.are.equal("511", jsnum.ParsePseudoBigInt("0o777n"))
        assert.are.equal("123", jsnum.ParsePseudoBigInt("000123n"))
        assert.are.equal("0", jsnum.ParsePseudoBigInt("0n"))
        assert.are.equal("-42", jsnum.ParseValidBigInt("-42"):String())
        assert.are.equal("0", jsnum.ParseValidBigInt("-0"):String())
        assert.are.equal(0, jsnum.ParseValidBigInt("-0"):Sign())
        assert.are.equal(-1, jsnum.NewPseudoBigInt("5", true):Sign())
        assert.are.equal(jsnum.NewPseudoBigInt("007", false), jsnum.NewPseudoBigInt("7", false))
    end)
end)
